      try { localStorage.setItem(KEY, String(V)); } catch (e) {}
      if (FIXED && V < 0.999) ensureCtx();   /* made during the slider touch, so iOS lets it run */
      if (gain) try { gain.gain.value = V; } catch (e) {}
      wake();
